import {memo, Suspense, useCallback, useContext, useMemo, useState} from 'react'

import {useQueryParamState} from '../../../../../../hooks/routes'
import {usePermission} from '../../../../../../hooks/usePermission'
import type {TestOccurrence} from '../../../../../../services/rest'
import type {TestOccurrenceId} from '../../../../../../types'
import {Permission, stringifyId, toTestOccurrenceId} from '../../../../../../types'
import Grid from '../../../../../common/Grid/Grid'
import RowGroup from '../../../../../common/Grid/RowGroup'
import InvestigationMuteButtons from '../../../../../packages/Tests/InvestigationMuteButtons/InvestigationMuteButtons'
import {makeGetTestOccurrencesList} from '../../../../../packages/Tests/Tests.selectors'
import {PipelinesTargetContext} from '../../../../PipelinesPages/contexts/targetContext'
import {isMuteInvestigateButtonEnabled} from '../../../../PipelinesPages/utils/featureToggles'

import DownloadTestsButton from './DownloadTestsButton/DownloadTestsButton.container'
import TableHeader from './TableHeader/TableHeader.container'
import TestItem from './TestItem/TestItem'
import type {Props} from './TestsList.types'

import styles from './TestsList.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

function TestsList({
  className,
  ids,
  buildId,
  projectId,
  fetchTestOccurrencesHandler,
  invocationsArg,
}: Props) {
  const pipelinesTarget = useContext(PipelinesTargetContext)

  const getTestOccurrencesList = useMemo(makeGetTestOccurrencesList, [])
  const testOccurrences = useAppSelector(state => getTestOccurrencesList(state, ids))

  const hasPermissionForInvestigation = usePermission(Permission.ASSIGN_INVESTIGATION, projectId)
  const hasPermissionForMute = usePermission(Permission.MANAGE_BUILD_PROBLEMS, projectId)
  const isAllowSelection =
    (hasPermissionForInvestigation || hasPermissionForMute) &&
    (!pipelinesTarget || isMuteInvestigateButtonEnabled)

  const [expandedTest, setExpandedTest] = useQueryParamState('expandedTest')
  const [selectedTests, setSelectedTests] = useState<TestOccurrenceId[]>([])

  const toggleExpandedTest = useCallback(
    (id?: TestOccurrenceId | null | undefined) => {
      const idString = stringifyId(id)
      setExpandedTest(expandedTest === idString ? null : idString)
    },
    [expandedTest, setExpandedTest],
  )
  const toggleSelectedTests = useCallback(
    (id?: TestOccurrenceId) => {
      if (id != null) {
        setSelectedTests(
          !selectedTests.includes(id)
            ? [...selectedTests, id]
            : selectedTests.filter(el => el !== id),
        )
      }
    },
    [selectedTests],
  )
  const onToggleSelectAllTests = useCallback(() => {
    const tests: TestOccurrenceId[] = []

    if (selectedTests.length !== testOccurrences.length) {
      testOccurrences.forEach(item => item.id != null && tests.push(item.id))
    }

    setSelectedTests(tests)
  }, [selectedTests.length, testOccurrences])

  const onInvestigationMuteAction = useCallback(() => {
    fetchTestOccurrencesHandler()
    setSelectedTests([])
  }, [fetchTestOccurrencesHandler])

  const renderTestItem = (testOccurrence: TestOccurrence) => {
    const itemBuildId = buildId ?? testOccurrence.build?.id
    return itemBuildId != null ? (
      <TestItem
        key={stringifyId(testOccurrence.id)}
        testOccurrenceId={testOccurrence.id}
        buildId={itemBuildId}
        selectedTests={selectedTests}
        expandedTest={expandedTest != null ? toTestOccurrenceId(expandedTest) : null}
        toggleExpandedTest={toggleExpandedTest}
        toggleSelectedTests={toggleSelectedTests}
        withSelectCheckbox={isAllowSelection}
        invocationsArg={invocationsArg}
      />
    ) : null
  }

  const hasTestOccurrences = testOccurrences.length > 0
  return (
    <div className={className}>
      {(pipelinesTarget == null || isMuteInvestigateButtonEnabled) && (
        <div data-test-tests-list-buttons className={styles.actions}>
          <Suspense>
            <InvestigationMuteButtons
              className={styles.investigationMuteButtons}
              projectId={projectId}
              testOccurrencesIds={selectedTests}
              onAction={onInvestigationMuteAction}
            />
          </Suspense>
          {buildId != null ? <DownloadTestsButton buildId={buildId} /> : null}
        </div>
      )}
      <Grid className={styles.grid}>
        {hasTestOccurrences && (
          <>
            <RowGroup span={1}>
              <TableHeader
                testsCount={testOccurrences.length}
                selectedTestsCount={selectedTests.length}
                withSelectAllCheckbox={isAllowSelection}
                onToggleSelectAllTests={onToggleSelectAllTests}
              />
            </RowGroup>
            <div className={styles.testsList} data-test-build-tests-list>
              {testOccurrences.map(renderTestItem)}
            </div>
          </>
        )}
      </Grid>
    </div>
  )
}

function TestsListContainer(props: Props) {
  return (
    <Suspense>
      <TestsList {...props} />
    </Suspense>
  )
}

export default memo(TestsListContainer)
