import Checkbox from '@jetbrains/ring-ui-built/components/checkbox/checkbox'
import type {QueryParams} from '@jetbrains/teamcity-ui/dist/utils'
import classNames from 'classnames'
import {memo, useCallback, useContext} from 'react'
import {graphql, useFragment} from 'react-relay'
import {useLocation} from 'react-router'

import {useSetQueryParams} from '../../../../../hooks/routes'
import {formatDurationWithMilliseconds} from '../../../../../utils/dateTimeUtils'
import {
  PipelinesTarget,
  PipelinesTargetContext,
} from '../../../PipelinesPages/contexts/targetContext'
import {getFilterQueryParams} from '../BuildTestsTab.utils'

import type {TestsFilterCountsFragment$key} from './__generated__/TestsFilterCountsFragment.graphql'
import TestScopeBreadcrumbs from './TestScopeBreadcrumbs/TestScopeBreadcrumbs'
import TestsSearch from './TestsSearch/TestsSearch'
import TestsStatusFilter from './TestsStatusFilter/TestsStatusFilter'
import {TestFilterStatus, getStatusQueryParam} from './TestsStatusFilter/TestsStatusFilter.utils'
import TestsViewSelect from './TestsViewSelect/TestsViewSelect'

import styles from './TestsFilter.module.css'

const countsFragment = graphql`
  fragment TestsFilterCountsFragment on TestCounters {
    all
    ignored
    success
    muted
    failed
    newFailed
    duration
  }
`

type Props = {
  countsKey: TestsFilterCountsFragment$key | null
}

function TestsFilter({countsKey}: Props) {
  const pipelinesTarget = useContext(PipelinesTargetContext)
  const location = useLocation()
  const setQueryParams = useSetQueryParams()
  const {name, onlyNew, withoutInvestigator} = getFilterQueryParams(location)
  const counts = useFragment(countsFragment, countsKey)
  const duration = counts?.duration
  const all = counts?.all ?? 0
  const ignored = counts?.ignored ?? 0
  const success = counts?.success ?? 0
  const muted = counts?.muted ?? 0
  const failed = counts?.failed ?? 0
  const newFailed = counts?.newFailed ?? 0
  const status = getStatusQueryParam(location)
  const withOnlyNewCheckbox = newFailed > 0 && status === TestFilterStatus.FAILED

  const onChangeQueryParams = useCallback(
    (newParams: QueryParams) => setQueryParams({...newParams, expandedTest: null, page: null}),
    [setQueryParams],
  )
  const onChangeStatus = useCallback(
    (newStatus: TestFilterStatus) => onChangeQueryParams({status: newStatus, onlyNew: null}),
    [onChangeQueryParams],
  )
  const onChangeName = useCallback(
    (value: string) => onChangeQueryParams({name: !value ? null : value}),
    [onChangeQueryParams],
  )
  const onChangeOnlyNew = useCallback(
    () => onChangeQueryParams({onlyNew: onlyNew ? null : 'true'}),
    [onChangeQueryParams, onlyNew],
  )
  const onChangeCurrentlyInvestigated = useCallback(
    () => onChangeQueryParams({withoutInvestigator: withoutInvestigator ? null : 'true'}),
    [onChangeQueryParams, withoutInvestigator],
  )

  return all > 0 ? (
    <div
      className={classNames(styles.filter, {
        [styles.jobDetailsPopupTarget]: pipelinesTarget === PipelinesTarget.JOB_DETAILS_POPUP,
        [styles.jobDetailsSidebarTarget]: pipelinesTarget === PipelinesTarget.JOB_DETAILS_SIDEBAR,
        [styles.withOnlyNewCheckbox]: withOnlyNewCheckbox,
      })}
      data-test-build-tests={'filter-wrapper'}
    >
      <div className={styles.firstFiltersLine}>
        <TestsViewSelect className={styles.viewSelect} onChangeQueryParams={onChangeQueryParams} />
        <TestsStatusFilter
          className={styles.statusFilter}
          status={status}
          all={all}
          success={success}
          failed={failed}
          ignored={ignored}
          muted={muted}
          onChangeStatus={onChangeStatus}
        />
        {duration != null && pipelinesTarget == null && (
          <div className={styles.totalDuration}>{`Total duration: ${formatDurationWithMilliseconds(
            duration,
            {
              alwaysShowSeconds: false,
              alwaysShowMilliseconds: false,
            },
          )}`}</div>
        )}
      </div>
      <div className={styles.seccondFiltersLine}>
        <TestsSearch className={styles.testsSearch} value={name} onChange={onChangeName} />
        {pipelinesTarget == null && (
          <div className={styles.filterWithoutInvestigator}>
            <Checkbox checked={withoutInvestigator} onChange={onChangeCurrentlyInvestigated}>
              <span>{'Without investigator'}</span>
            </Checkbox>
          </div>
        )}
        {withOnlyNewCheckbox ? (
          <div className={styles.filterOnlyNew}>
            <Checkbox checked={onlyNew} onChange={onChangeOnlyNew}>
              <span>{'Only new'}</span>
              <span className={styles.count} data-test-build-tests={'new-failed-label'}>
                {` ${newFailed}`}
              </span>
            </Checkbox>
          </div>
        ) : null}
      </div>
      <TestScopeBreadcrumbs className={styles.scopeFilter} />
    </div>
  ) : null
}

export default memo(TestsFilter)
