import {lazy, Suspense} from 'react'

import type {ContainerProps} from './TestHistoryChart.types'

const TestHistoryChartLazy = lazy(
  () =>
    import(
      /* webpackChunkName: "TestHistoryChart" */
      './TestHistoryChart'
    ),
)

function TestHistoryChart(props: ContainerProps) {
  return (
    <Suspense fallback="">
      <TestHistoryChartLazy {...props} />
    </Suspense>
  )
}

export default TestHistoryChart
