import LoaderInline from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import classNames from 'classnames'
import {memo, Suspense, useContext} from 'react'
import type {EntryPointProps} from 'react-relay'
import {EntryPointContainer} from 'react-relay'
import {useLocation} from 'react-router'

import type {BuildId, ProjectId} from '../../../../types'
import {useFetchBuildTestCounters} from '../../../packages/Tests/Tests.hooks'
import {PipelinesTarget, PipelinesTargetContext} from '../../PipelinesPages/contexts/targetContext'

import type {BuildTestsTabCountsQuery} from './__generated__/BuildTestsTabCountsQuery.graphql'
import {countsQuery, getCountsVariables} from './BuildTestsTab.queries'
import {getFilterQueryParams} from './BuildTestsTab.utils'
import type {TestScopesViewEntryPoint} from './TestScopesView/TestScopesView.entryPoint'
import TestsFilter from './TestsFilter/TestsFilter'
import {ViewType} from './TestsFilter/TestsViewSelect/TestsViewSelect.utils'
import TestsView from './TestsView/TestsView'

import styles from './BuildTestsTab.module.css'

export type NestedEntryPoints = {
  testScopesView?: typeof TestScopesViewEntryPoint
}

export type Props = {
  buildId: BuildId
  buildLocator?: string
  projectId?: ProjectId | null
}

type Queries = {counts: BuildTestsTabCountsQuery}

function BuildTestsTab({
  entryPoints,
  queries,
  props,
}: EntryPointProps<Queries, NestedEntryPoints, Props, {}>) {
  const pipelinesTarget = useContext(PipelinesTargetContext)
  const {projectId, buildId, buildLocator} = props
  const location = useLocation()
  const {view} = getFilterQueryParams(location)

  const {testOccurrences} = useFetchBuildTestCounters(
    buildId,
    buildLocator,
    countsQuery,
    queries.counts,
    getCountsVariables,
  )

  return (
    <div
      className={classNames({
        [styles.jobDetailsPopupTarget]: pipelinesTarget === PipelinesTarget.JOB_DETAILS_POPUP,
        [styles.jobDetailsSidebarTarget]: pipelinesTarget === PipelinesTarget.JOB_DETAILS_SIDEBAR,
      })}
    >
      <TestsFilter countsKey={testOccurrences?.testCounters ?? null} />
      <div className={styles.content}>
        {view === ViewType.TESTS ? (
          <TestsView buildId={buildId} projectId={projectId} />
        ) : (
          <Suspense fallback={<LoaderInline>{'Loading...'}</LoaderInline>}>
            {entryPoints.testScopesView && (
              <EntryPointContainer
                entryPointReference={entryPoints.testScopesView}
                props={{buildId, countsKey: testOccurrences?.testCounters ?? null}}
              />
            )}
          </Suspense>
        )}
      </div>
    </div>
  )
}

export default memo(BuildTestsTab)
export type BuildTestsTabComponent = typeof BuildTestsTab
