import Button from '@jetbrains/ring-ui-built/components/button/button'
import ButtonGroup from '@jetbrains/ring-ui-built/components/button-group/button-group'
import classNames from 'classnames'
import {memo, useCallback} from 'react'

import {TestFilterStatus, TestStatusName} from './TestsStatusFilter.utils'

import styles from './TestsStatusFilter.module.css'

type Props = {
  className?: string
  status: TestFilterStatus
  all: number
  success: number
  failed: number
  muted: number
  ignored: number
  onChangeStatus: (status: TestFilterStatus) => unknown
}

type StatusButtonProps = {
  active: boolean
  type: TestFilterStatus
  count: number
  onClick: (status: TestFilterStatus) => unknown
}

function StatusButton({type, count, active, onClick: onClickExternal}: StatusButtonProps) {
  const onClick = useCallback(() => onClickExternal(type), [onClickExternal, type])

  return count > 0 || active || type === TestFilterStatus.ALL ? (
    <Button
      className={classNames(styles.stateButton, {[styles.active]: active})}
      active={active}
      onClick={onClick}
      data-test-build-tests={`${type.toLowerCase()}-button`}
      key={type}
    >
      {TestStatusName[type]}
      <span className={styles.count}>{count}</span>
    </Button>
  ) : null
}

function TestStatusFilter({
  className,
  status,
  all,
  success,
  failed,
  muted,
  ignored,
  onChangeStatus,
}: Props) {
  return (
    <div className={classNames(className, styles.filter)}>
      <ButtonGroup>
        <StatusButton
          active={status === TestFilterStatus.ALL}
          type={TestFilterStatus.ALL}
          count={all}
          onClick={onChangeStatus}
        />
        <StatusButton
          active={status === TestFilterStatus.PASSED}
          type={TestFilterStatus.PASSED}
          count={success}
          onClick={onChangeStatus}
        />
        <StatusButton
          active={status === TestFilterStatus.FAILED}
          type={TestFilterStatus.FAILED}
          count={failed}
          onClick={onChangeStatus}
        />
        <StatusButton
          active={status === TestFilterStatus.MUTED}
          type={TestFilterStatus.MUTED}
          count={muted}
          onClick={onChangeStatus}
        />
        <StatusButton
          active={status === TestFilterStatus.IGNORED}
          type={TestFilterStatus.IGNORED}
          count={ignored}
          onClick={onChangeStatus}
        />
      </ButtonGroup>
    </div>
  )
}

export default memo(TestStatusFilter)
